import argparse
import json
import sys
import logging
from pathlib import Path
from datetime import datetime, timezone

from utils.logging_config import get_logger

def load_config(config_path: str = "config.yaml") -> dict:
    """Load configuration from YAML file."""
    import yaml
    with open(config_path, "r") as f:
        return yaml.safe_load(f)

def load_runtime_status(runtime_status_path: str) -> dict:
    """Load the runtime status generated by T023a."""
    path = Path(runtime_status_path)
    if not path.exists():
        raise FileNotFoundError(f"Runtime status file not found: {runtime_status_path}")
    with open(path, "r") as f:
        return json.load(f)

def check_stopping_rule(runtime_status: dict, config: dict) -> tuple:
    """
    Check if effective_sample_size < study.min_sample_size.
    Returns (should_halt: bool, reason: str).
    """
    effective_sample_size = runtime_status.get("effective_sample_size", 0)
    min_sample_size = config.get("study", {}).get("min_sample_size", 40)
    
    if effective_sample_size < min_sample_size:
        reason = f"Effective sample size ({effective_sample_size}) is below minimum required ({min_sample_size}). Study is underpowered."
        return True, reason
    
    return False, "Sample size sufficient."

def generate_underpowered_report(
    effective_sample_size: int, 
    threshold: int, 
    reason: str, 
    output_path: str
) -> dict:
    """
    Generate the underpowered report JSON as per T027a specification.
    Schema: { "effective_sample_size": int, "threshold": int, "reason": str, "timestamp": str }
    """
    report = {
        "effective_sample_size": effective_sample_size,
        "threshold": threshold,
        "reason": reason,
        "timestamp": datetime.now(timezone.utc).isoformat()
    }
    
    output_file = Path(output_path)
    output_file.parent.mkdir(parents=True, exist_ok=True)
    
    with open(output_file, "w") as f:
        json.dump(report, f, indent=2)
    
    return report

def main():
    parser = argparse.ArgumentParser(description="Check stopping rule and generate underpowered report.")
    parser.add_argument("--runtime-status", type=str, default="data/results/runtime_status.json",
                        help="Path to runtime status JSON generated by T023a")
    parser.add_argument("--config", type=str, default="config.yaml",
                        help="Path to config.yaml")
    parser.add_argument("--output", type=str, default="data/results/underpowered_report.json",
                        help="Path to write the underpowered report")
    parser.add_argument("--threshold", type=int, default=0,
                        help="Current threshold value to include in report (if known)")
    
    args = parser.parse_args()
    
    logger = get_logger(__name__)
    logger.info("Starting stopping rule check (T027a).")
    
    try:
        config = load_config(args.config)
        runtime_status = load_runtime_status(args.runtime_status)
        
        effective_sample_size = runtime_status.get("effective_sample_size", 0)
        threshold = args.threshold
        if threshold == 0:
            # Try to infer threshold from runtime status or config if not provided
            threshold = runtime_status.get("threshold", config.get("pilot", {}).get("threshold", 0))
        
        should_halt, reason = check_stopping_rule(runtime_status, config)
        
        if should_halt:
            logger.warning(f"Stopping rule triggered: {reason}")
            report = generate_underpowered_report(
                effective_sample_size=effective_sample_size,
                threshold=threshold,
                reason=reason,
                output_path=args.output
            )
            logger.info(f"Underpowered report written to {args.output}")
            logger.info(f"Report content: {report}")
            # Halt execution as per T027 requirement
            sys.exit(1)
        else:
            logger.info("Stopping rule check passed. Study is sufficiently powered.")
            # Ensure we don't create a report if not needed, or create a 'pass' artifact if required by downstream
            # Based on T027a spec, we only generate the report if the condition is met.
            
    except FileNotFoundError as e:
        logger.error(f"File not found: {e}")
        sys.exit(1)
    except Exception as e:
        logger.error(f"Unexpected error during stopping rule check: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()